import{_ as t,o,c as a,au as r}from"./chunks/framework.BTTEhLNX.js";const d="/krawler-ekosystem/assets/forecast-pipeline.BJ7Vymcx.svg",b=JSON.parse('{"title":"krawler-meteofrance","description":"A Krawler job designed to scrape data from the Météo-France public API","frontmatter":{"title":"krawler-meteofrance","description":"A Krawler job designed to scrape data from the Météo-France public API"},"headers":[],"relativePath":"packages/krawler-meteofrance/index.md","filePath":"packages/krawler-meteofrance/index.md"}'),i={name:"packages/krawler-meteofrance/index.md"};function n(s,e,l,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="krawler-meteofrance" tabindex="-1">krawler-meteofrance <a class="header-anchor" href="#krawler-meteofrance" aria-label="Permalink to &quot;krawler-meteofrance&quot;">​</a></h1><p><em>A Krawler job designed to scrape data from the Météo-France public API</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A <a href="https://kalisio.github.io/krawler/" target="_blank" rel="noreferrer">Krawler</a> based service to download diverse datasets from the public <a href="https://portail-api.meteofrance.fr/web/fr/" target="_blank" rel="noreferrer">Météo-France API portal</a>.</p><h2 id="paquetobs" tabindex="-1">paquetobs <a class="header-anchor" href="#paquetobs" aria-label="Permalink to &quot;paquetobs&quot;">​</a></h2><p>The <strong>paquetobs</strong> job files enable the scraping of <a href="https://donneespubliques.meteofrance.fr/?fond=produit&amp;id_produit=93&amp;id_rubrique=32" target="_blank" rel="noreferrer">real-time observations</a> from all weather stations of the French network at hourly and/or sub-hourly intervals (every 6 minutes). These data are exposed by the public API <a href="https://portail-api.meteofrance.fr/web/fr/api/DonneesPubliquesPaquetObservation" target="_blank" rel="noreferrer">Package Observations</a>.</p><h3 id="paquetobs-stations" tabindex="-1">paquetobs-stations <a class="header-anchor" href="#paquetobs-stations" aria-label="Permalink to &quot;paquetobs-stations&quot;">​</a></h3><p>This job scrapes the stations. The main collected properties are:</p><ul><li><strong>id</strong>, the id of the station</li><li><strong>name</strong>, the name of the station</li><li><strong>location</strong>, the location of the station</li></ul><p>The station data are stored in compliance with the <strong>GeoJSON</strong> standard.</p><h4 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>PAQUETOBS_TOKEN</code></td><td>The token to use the <strong>paquetobs</strong> API</td></tr><tr><td><code>DEPARTMENTS</code></td><td>The list of departments used to filter the collected observations, e.g, <code>&quot;11,09,31&quot;</code></td></tr><tr><td><code>STATIONS</code></td><td>The list of station ids used to filter the collected observations, e.g, <code>&quot;09099001,09301001&quot;</code></td></tr><tr><td><code>DB_URL</code></td><td>the database url. By default: <code>mongodb://localhost:27017/meteofrance</code>.</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h3 id="paquetobs-observations" tabindex="-1">paquetobs-observations <a class="header-anchor" href="#paquetobs-observations" aria-label="Permalink to &quot;paquetobs-observations&quot;">​</a></h3><p>This job scrapes the observations. The basic collected properties are:</p><ul><li><strong>id</strong>, the id of the station</li><li><strong>name</strong>, the name of the station</li><li><strong>temperature</strong> (°),</li><li><strong>humidity</strong> (%),</li><li><strong>wind direction</strong> (°),</li><li><strong>wind speed</strong> (m/s),</li><li><strong>precipitation</strong> (mm/h)</li></ul><p>The observation data are stored in compliance with the <strong>GeoJSON</strong> standard.</p><h4 id="configuration-1" tabindex="-1">Configuration <a class="header-anchor" href="#configuration-1" aria-label="Permalink to &quot;Configuration&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>PAQUETOBS_TOKEN</code></td><td>The <strong>paquetobs</strong> API token.</td></tr><tr><td><code>FREQUENCY</code></td><td>The frequency of the observations to collect. It must be <code>horaire</code> or <code>infrahoraire-6m</code>. Default value is <code>horaire</code>.</td></tr><tr><td><code>LATENCY</code></td><td>The latency of the observations to collect. It must be <code>horaire</code> or <code>infrahoraire-6m</code>. Default value is <code>horaire</code>.</td></tr><tr><td><code>TTL</code></td><td>The retention period in seconds of the data. By default: <code>7 * 24 * 60 * 60</code> (~7 days)</td></tr><tr><td><code>DB_URL</code></td><td>the database url. By default: <code>mongodb://localhost:27017/meteofrance</code>.</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="forecast-pipeline-arome-arpege" tabindex="-1">Forecast Pipeline (AROME / ARPEGE) <a class="header-anchor" href="#forecast-pipeline-arome-arpege" aria-label="Permalink to &quot;Forecast Pipeline (AROME / ARPEGE)&quot;">​</a></h2><p><img src="'+d+'" alt="forecast-pipeline"></p><p>These jobs download forecast data from the public Météo-France API:</p><ul><li><strong><a href="https://portail-api.meteofrance.fr/web/fr/api/PaquetAROME" target="_blank" rel="noreferrer">AROME</a></strong> – High-resolution regional model</li><li><strong><a href="https://portail-api.meteofrance.fr/web/fr/api/PaquetARPEGE" target="_blank" rel="noreferrer">ARPEGE</a></strong> – Global model</li></ul><p>Files are retrieved in <strong>GRIB2</strong> format.</p><h3 id="available-jobs" tabindex="-1">Available Jobs <a class="header-anchor" href="#available-jobs" aria-label="Permalink to &quot;Available Jobs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Job</th><th>Type</th><th>Resolution</th><th>Coverage</th></tr></thead><tbody><tr><td><code>arome-france</code></td><td>AROME</td><td>0.025°</td><td>France</td></tr><tr><td><code>arome-france-high</code></td><td>AROME</td><td>0.01°</td><td>France</td></tr><tr><td><code>arpege-europe</code></td><td>ARPEGE</td><td>0.1°</td><td>Europe</td></tr><tr><td><code>arpege-world</code></td><td>ARPEGE</td><td>0.25°</td><td>Global</td></tr></tbody></table><h3 id="configuration-2" tabindex="-1">Configuration <a class="header-anchor" href="#configuration-2" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DATA_SOURCE</code></td><td>Source of the data (<code>meteofrance</code> or <code>data-gouv</code>)</td></tr><tr><td><code>AROME_TOKEN</code></td><td>API token for AROME</td></tr><tr><td><code>ARPEGE_TOKEN</code></td><td>API token for ARPEGE</td></tr><tr><td><code>OUTPUT_DIR</code></td><td>Base directory for downloaded files</td></tr><tr><td><code>WORKERS_LIMIT</code></td><td>Maximum number of concurrent downloads</td></tr><tr><td><code>OLDEST_RUN_INTERVAL_MS</code></td><td>Max allowed run age</td></tr><tr><td><code>RUN_TIMES</code></td><td>Override model run times</td></tr><tr><td><code>PACKAGES</code></td><td>Override packages</td></tr><tr><td><code>FORECAST_TIMES</code></td><td>Override forecast steps</td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>',29)])])}const f=t(i,[["render",n]]);export{b as __pageData,f as default};
